import textwrap
from test.support import SuppressCrashReport, script_helper

def _t():
    code = textwrap.dedent('\n            import atexit\n\n            def f(msg):\n                print(msg)\n\n            atexit.register(f, "one")\n            atexit.register(f, "two")\n        ')
    res = script_helper.assert_python_ok('-c', code)
    assert res.out.decode().splitlines() == ['two', 'one'], ('assertEqual', res.out.decode().splitlines(), ['two', 'one'])
    assert not res.err, ('assertFalse', res.err)
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

import textwrap
from test.support import SuppressCrashReport, script_helper

def _t():
    code = textwrap.dedent('\n            import sys\n            import atexit as atexit1\n            del sys.modules[\'atexit\']\n            import atexit as atexit2\n            del sys.modules[\'atexit\']\n\n            assert atexit2 is not atexit1\n\n            atexit1.register(print, "atexit1")\n            atexit2.register(print, "atexit2")\n        ')
    res = script_helper.assert_python_ok('-c', code)
    assert res.out.decode().splitlines() == ['atexit2', 'atexit1'], ('assertEqual', res.out.decode().splitlines(), ['atexit2', 'atexit1'])
    assert not res.err, ('assertFalse', res.err)
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
